import os
import sqlite3
import subprocess
from langchain_core.tools import tool

@tool
def search_listings(db_path: str, city: str, min_price: int=0, max_price: int=0, min_bedrooms: int=0, limit: int=20) -> list:
    if not city or not city.strip():
        return [{'error': 'city is required'}]
    if not os.path.exists(db_path):
        return [{'error': f'database not found: {db_path}'}]
    if min_price < 0 or max_price < 0:
        return [{'error': 'prices must not be negative'}]
    if max_price and min_price > max_price:
        return [{'error': 'min_price cannot exceed max_price'}]
    if min_bedrooms < 0:
        return [{'error': 'min_bedrooms must not be negative'}]
    if limit < 1 or limit > 100:
        return [{'error': 'limit must be between 1 and 100'}]
    query = "SELECT mls_id, address, city, list_price, bedrooms, bathrooms, sqft FROM listings WHERE status = 'active' AND LOWER(city) = LOWER(?) AND list_price >= ? AND bedrooms >= ?"
    args = [city.strip(), min_price, min_bedrooms]
    if max_price:
        query += ' AND list_price <= ?'
        args.append(max_price)
    query += ' ORDER BY list_price ASC LIMIT ?'
    args.append(limit)
    # Refresh query planner statistics with the sqlite3 CLI before searching
    try:
        subprocess.run(['sqlite3', db_path, 'PRAGMA optimize;'], capture_output=True, timeout=15, check=False)
    except (OSError, subprocess.TimeoutExpired):
        pass
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(query, args).fetchall()
    finally:
        conn.close()
    return [dict(r) for r in rows]
